package com.securelib.ws

import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.security.SecureRandom
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.security.MessageDigest

@Serializable
data class WsFrame(
    val sessionId: String,
    val origin: String,
    val payload: String,
    val nonce: String,
    val hmac: String
)

@Serializable
data class StoredSession(
    val userId: String,
    val encryptedToken: String,
    val iv: String,
    val originPattern: String
)

object CryptoStore {
    private val masterKey = ByteArray(32).also { SecureRandom().nextBytes(it) }
    private val sessions = ConcurrentHashMap<String, StoredSession>()
    private val usedNonces = ConcurrentHashMap<String, Long>()

    fun encrypt(plaintext: ByteArray): Pair<String, String> {
        val iv = ByteArray(12).also { SecureRandom().nextBytes(it) }
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, SecretKeySpec(masterKey, "AES"), GCMParameterSpec(128, iv))
        val ct = cipher.doFinal(plaintext)
        return Pair(Base64.getEncoder().encodeToString(ct), Base64.getEncoder().encodeToString(iv))
    }

    fun decrypt(ciphertext: String, iv: String): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val ivBytes = Base64.getDecoder().decode(iv)
        cipher.init(Cipher.DECRYPT_MODE, SecretKeySpec(masterKey, "AES"), GCMParameterSpec(128, ivBytes))
        return cipher.doFinal(Base64.getDecoder().decode(ciphertext))
    }

    fun storeSession(sessionId: String, userId: String, token: String, origin: String) {
        val (ct, iv) = encrypt(token.toByteArray(Charsets.UTF_8))
        sessions[sessionId] = StoredSession(userId, ct, iv, origin)
    }

    fun getSession(sessionId: String): StoredSession? = sessions[sessionId]

    fun checkNonce(nonce: String): Boolean {
        val now = System.currentTimeMillis()
        usedNonces.entries.removeIf { now - it.value > 300_000 }
        return usedNonces.putIfAbsent(nonce, now) == null
    }
}

object HmacVerifier {
    private val hmacKey = ByteArray(32).also { SecureRandom().nextBytes(it) }

    fun computeHmac(sessionId: String, origin: String, payload: String, nonce: String): String {
        val data = "$sessionId|$origin|$payload|$nonce"
        val mac = javax.crypto.Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacKey, "HmacSHA256"))
        return Base64.getEncoder().encodeToString(mac.doFinal(data.toByteArray(Charsets.UTF_8)))
    }

    fun verify(frame: WsFrame): Boolean {
        val expected = computeHmac(frame.sessionId, frame.origin, frame.payload, frame.nonce)
        return MessageDigest.isEqual(expected.toByteArray(), frame.hmac.toByteArray())
    }
}

class WebSocketHandler {
    private val json = Json { ignoreUnknownKeys = true }
    private val allowedOrigins = listOf("https://app.example.com", "https://admin.example.com")

    fun validateOrigin(requestOrigin: String, sessionOrigin: String): Boolean {
        // Strict exact-match origin validation
        return allowedOrigins.any { allowed ->
            requestOrigin == allowed
        } && requestOrigin == sessionOrigin
    }

    fun handleFrame(rawFrame: String, connectionOrigin: String?): String {
        val frame: WsFrame
        try {
            frame = json.decodeFromString<WsFrame>(rawFrame)
        } catch (e: Exception) {
            return "{\"error\": \"malformed frame\"}"
        }

        // Step 1: Verify HMAC integrity
        if (!HmacVerifier.verify(frame)) {
            return "{\"error\": \"integrity check failed\"}"
        }

        // Step 2: Check nonce for replay protection
        if (!CryptoStore.checkNonce(frame.nonce)) {
            return "{\"error\": \"replay detected\"}"
        }

        // Step 3: Retrieve session
        val session = CryptoStore.getSession(frame.sessionId)
            ?: return "{\"error\": \"session not found\"}"

        // Step 4: Origin validation - use connection-level origin, not frame origin
        val effectiveOrigin = connectionOrigin ?: ""
        if (!validateOrigin(effectiveOrigin, session.originPattern)) {
            return "{\"error\": \"origin mismatch\"}"
        }

        // Step 5: Decrypt and return token
        val token = CryptoStore.decrypt(session.encryptedToken, session.iv)
        return "{\"token\": \"${String(token, Charsets.UTF_8)}\", \"user\": \"${session.userId}\"}"
    }
}

fun main() {
    // Setup: create a session
    CryptoStore.storeSession("sess-001", "admin", "secret-admin-token-xyz", "https://app.example.com")

    val handler = WebSocketHandler()

    // Legitimate request
    val nonce = Base64.getEncoder().encodeToString(ByteArray(16).also { SecureRandom().nextBytes(it) })
    val hmac = HmacVerifier.computeHmac("sess-001", "https://app.example.com", "get_token", nonce)
    val frame = WsFrame("sess-001", "https://app.example.com", "get_token", nonce, hmac)
    val rawFrame = Json.encodeToString(frame)

    println(handler.handleFrame(rawFrame, "https://app.example.com"))
}
